from pathlib import Path

p = Path('night.py')
s = p.read_text()

# Add Cloudflare prewarm state to Night.__init__.
anchor = '''        self.shutdown_hooks: list[t.Callable] = []\n'''
replacement = '''        self.shutdown_hooks: list[t.Callable] = []\n        self._cloudflare_response_class = None\n        self._cloudflare_rpc_from = None\n        self._cloudflare_rpc_to = None\n        self._cloudflare_prewarmed = False\n'''
if anchor not in s:
    raise SystemExit('Night.__init__ anchor missing')
s = s.replace(anchor, replacement, 1)

# Replace cloudflare_rpc lazy imports with cached/prewarmed codecs and add prewarm API.
old_rpc = '''    async def cloudflare_rpc(\n        self,\n        method: str,\n        args: t.Any = None,\n        kwargs: t.Any = None,\n    ) -> t.Any:\n        \"\"\"Invoke a registered ``@app.rpc`` method over Workers RPC.\n\n        The Cloudflare runtime SDK owns the Python <-> JavaScript/RPC value\n        conversion. Keeping this bridge lazy preserves Night's zero-dependency\n        behavior outside Cloudflare Workers.\n        \"\"\"\n        try:\n            from workers.rpc import python_from_rpc, python_to_rpc\n        except ImportError as exc:\n            raise RuntimeError(\n                \"Cloudflare RPC requires workers-runtime-sdk inside a Python Worker\"\n            ) from exc\n\n        fn = self.rpc_methods.get(str(method))\n        if fn is None:\n            raise KeyError(f\"Unknown Night RPC method: {method}\")\n\n        call_args = python_from_rpc(args) if args is not None else []\n        call_kwargs = python_from_rpc(kwargs) if kwargs is not None else {}\n'''
new_rpc = '''    def cloudflare_prewarm(self, *, response_class: t.Any = None, rpc: bool = False) -> \"Night\":\n        \"\"\"Prewarm snapshot-safe Cloudflare adapter state.\n\n        Cloudflare Python Workers snapshot top-level Python execution at deploy\n        time. Calling this after route registration moves Workers SDK imports and\n        pure-Python adapter cache warming out of the first live request. No I/O\n        or request-scoped state is retained.\n        \"\"\"\n        if response_class is None:\n            try:\n                from workers import Response as response_class\n            except ImportError as exc:\n                raise RuntimeError(\n                    \"Cloudflare prewarm requires workers-runtime-sdk inside a Python Worker\"\n                ) from exc\n        self._cloudflare_response_class = response_class\n\n        if rpc:\n            try:\n                from workers.rpc import python_from_rpc, python_to_rpc\n            except ImportError as exc:\n                raise RuntimeError(\n                    \"Cloudflare RPC prewarm requires workers-runtime-sdk inside a Python Worker\"\n                ) from exc\n            self._cloudflare_rpc_from = python_from_rpc\n            self._cloudflare_rpc_to = python_to_rpc\n\n        # Warm only deterministic, snapshot-safe Python paths. These calls do no\n        # network/storage I/O and never execute user endpoints.\n        urllib.parse.urlsplit(\"https://edge.invalid/__night_prewarm__?x=1\")\n        _ = \"GET\".encode(\"latin-1\").decode(\"latin-1\")\n        for method in tuple(self._dynamic_method_routes):\n            self._rebuild_dynamic_matcher(method)\n        self._cloudflare_prewarmed = True\n        return self\n\n    async def cloudflare_rpc(\n        self,\n        method: str,\n        args: t.Any = None,\n        kwargs: t.Any = None,\n    ) -> t.Any:\n        \"\"\"Invoke a registered ``@app.rpc`` method over Workers RPC.\"\"\"\n        python_from_rpc = self._cloudflare_rpc_from\n        python_to_rpc = self._cloudflare_rpc_to\n        if python_from_rpc is None or python_to_rpc is None:\n            try:\n                from workers.rpc import python_from_rpc, python_to_rpc\n            except ImportError as exc:\n                raise RuntimeError(\n                    \"Cloudflare RPC requires workers-runtime-sdk inside a Python Worker\"\n                ) from exc\n            self._cloudflare_rpc_from = python_from_rpc\n            self._cloudflare_rpc_to = python_to_rpc\n\n        fn = self.rpc_methods.get(str(method))\n        if fn is None:\n            raise KeyError(f\"Unknown Night RPC method: {method}\")\n\n        call_args = python_from_rpc(args) if args is not None else []\n        call_kwargs = python_from_rpc(kwargs) if kwargs is not None else {}\n'''
if old_rpc not in s:
    raise SystemExit('cloudflare_rpc anchor missing')
s = s.replace(old_rpc, new_rpc, 1)

# Cache Response class in cloudflare_fetch.
s = s.replace(
'''        try:\n            if response_class is None:\n                from workers import Response as response_class\n        except ImportError as exc:\n            raise RuntimeError(\n                \"Cloudflare fetch integration requires workers-runtime-sdk\"\n            ) from exc\n''',
'''        if response_class is None:\n            response_class = self._cloudflare_response_class\n        if response_class is None:\n            try:\n                from workers import Response as response_class\n            except ImportError as exc:\n                raise RuntimeError(\n                    \"Cloudflare fetch integration requires workers-runtime-sdk\"\n                ) from exc\n            self._cloudflare_response_class = response_class\n''', 1)

# Introduce a shared HTTP core that returns Night Response instead of forcing ASGI events.
call_start = s.index('    async def __call__(self, scope, receive, send):\n')
call_end = s.index('    async def _handle_lifespan(self, receive, send):\n', call_start)
old_call = s[call_start:call_end]
new_call = '''    async def _handle_http_request(\n        self,\n        req: Request,\n        scope: dict[str, t.Any],\n        *,\n        path: str,\n        method: str,\n    ) -> Response:\n        # Automatic OPTIONS and HEAD support.\n        if method == \"OPTIONS\":\n            allowed = self._allowed_methods_for_path(path)\n            if allowed:\n                allowed_with_opts = set(allowed) | {\"OPTIONS\"}\n                return Response(b\"\", status=204, headers={\"allow\": \",\".join(sorted(allowed_with_opts))})\n            return PlainTextResponse(\"Not Found\", status=404)\n\n        is_head = method == \"HEAD\"\n        if is_head:\n            req.scope = dict(req.scope)\n            req.scope[\"method\"] = \"GET\"\n            method = \"GET\"\n\n        try:\n            if self.middlewares:\n                async def call_next(i: int = 0) -> Response:\n                    if i >= len(self.middlewares):\n                        return await self._dispatch(req, path, method)\n                    mw = self.middlewares[i]\n                    async def nxt() -> Response:\n                        return await call_next(i + 1)\n                    return await mw(req, nxt)\n                resp = await call_next(0)\n            else:\n                resp = await self._dispatch(req, path, method)\n        except HTTPError as he:\n            handler = self._find_error_handler(he)\n            if handler is not None:\n                out = handler(req, he)\n                if inspect.isawaitable(out):\n                    out = await t.cast(t.Awaitable, out)\n                resp = self._coerce_response(out)\n            else:\n                error_headers = {}\n                if isinstance(he, MethodNotAllowed) and he.allowed:\n                    error_headers[\"allow\"] = \",\".join(he.allowed)\n                if isinstance(he, ValidationError):\n                    resp = JSONResponse({\"errors\": he.errors}, status=he.status, headers=error_headers)\n                elif self.debug:\n                    resp = PlainTextResponse(f\"{he.status} {he.detail}\", status=he.status, headers=error_headers)\n                else:\n                    resp = PlainTextResponse(he.detail or \"Error\", status=he.status, headers=error_headers)\n        except Exception as e:\n            handler = self._find_error_handler(e)\n            if handler is not None:\n                out = handler(req, e)\n                if inspect.isawaitable(out):\n                    out = await t.cast(t.Awaitable, out)\n                resp = self._coerce_response(out)\n            else:\n                if self.debug:\n                    resp = PlainTextResponse(traceback.format_exc(), status=500)\n                else:\n                    resp = PlainTextResponse(\"Internal Server Error\", status=500)\n\n        if is_head:\n            content_length = resp.headers.get(\"content-length\")\n            resp.body = b\"\"\n            if content_length is not None:\n                resp.headers[\"content-length\"] = content_length\n            else:\n                resp.headers.pop(\"content-length\", None)\n\n        if self.secret_key and \"_session\" in req.scope:\n            current = json.dumps(req.scope[\"_session\"], sort_keys=True, separators=(\",\", \":\"))\n            original = req.scope.get(\"_session_original\", \"\")\n            if current != original or req.scope.get(\"_session_regenerated\"):\n                encoded = base64.urlsafe_b64encode(current.encode()).decode().rstrip(\"=\")\n                signature = hmac.new(self.secret_key, encoded.encode(), hashlib.sha256).hexdigest()\n                if len(encoded) + len(signature) + len(\"night_session=; Path=/; HttpOnly; SameSite=Lax\") > MAX_SESSION_COOKIE_SIZE:\n                    resp = PlainTextResponse(\"Internal Server Error\" if not self.debug else \"Session data exceeds cookie size limit\", status=500)\n                else:\n                    secure = self.session_secure if self.session_secure is not None else scope.get(\"scheme\") == \"https\"\n                    resp.set_cookie(\"night_session\", encoded + \".\" + signature, httponly=True, secure=secure, samesite=\"Lax\")\n        return resp\n\n    async def __call__(self, scope, receive, send):\n        if scope.get(\"type\") == \"websocket\":\n            await self._handle_websocket(scope, receive, send)\n            return\n        if scope.get(\"type\") == \"lifespan\":\n            await self._handle_lifespan(receive, send)\n            return\n        if scope.get(\"type\") != \"http\":\n            return\n\n        if self.secret_key:\n            request_scope = dict(scope)\n            request_scope[\"session_secret\"] = self.secret_key\n        else:\n            request_scope = scope\n        req = Request(scope=request_scope, receive=receive, send=send, max_body_size=self.max_body_size)\n        method = (request_scope.get(\"method\") or \"GET\").upper()\n        path = request_scope.get(\"path\") or \"/\"\n        token = _current_request.set(req)\n        try:\n            resp = await self._handle_http_request(req, request_scope, path=path, method=method)\n            await resp(request_scope, receive, send)\n        finally:\n            _current_request.reset(token)\n\n'''
s = s[:call_start] + new_call + s[call_end:]

# Replace Cloudflare ASGI event capture with direct shared-core dispatch.
old_tail = '''        received = False\n        async def receive():\n            nonlocal received\n            if received:\n                return {\"type\": \"http.request\", \"body\": b\"\", \"more_body\": False}\n            received = True\n            return {\"type\": \"http.request\", \"body\": body, \"more_body\": False}\n\n        events: list[dict[str, t.Any]] = []\n        async def send(event):\n            events.append(event)\n\n        await self(scope, receive, send)\n        start = next((event for event in events if event.get(\"type\") == \"http.response.start\"), None)\n        if start is None:\n            raise RuntimeError(\"Night produced no HTTP response start event\")\n        chunks = [\n            event.get(\"body\", b\"\")\n            for event in events\n            if event.get(\"type\") == \"http.response.body\"\n        ]\n        web_headers = [\n            (key.decode(\"latin-1\"), value.decode(\"latin-1\"))\n            for key, value in start.get(\"headers\", ())\n        ]\n        return response_class(\n            b\"\".join(chunks),\n            status=int(start[\"status\"]),\n            headers=web_headers,\n        )\n'''
new_tail = '''        received = False\n        async def receive():\n            nonlocal received\n            if received:\n                return {\"type\": \"http.request\", \"body\": b\"\", \"more_body\": False}\n            received = True\n            return {\"type\": \"http.request\", \"body\": body, \"more_body\": False}\n\n        async def send(_event):\n            return None\n\n        if self.secret_key:\n            request_scope = dict(scope)\n            request_scope[\"session_secret\"] = self.secret_key\n        else:\n            request_scope = scope\n        req = Request(scope=request_scope, receive=receive, send=send, max_body_size=self.max_body_size)\n        token = _current_request.set(req)\n        try:\n            resp = await self._handle_http_request(req, request_scope, path=decoded_path, method=method)\n        finally:\n            _current_request.reset(token)\n\n        web_headers = [(k, v) for k, v in resp.headers.items() if k != \"set-cookie\"]\n        web_headers.extend(resp.raw_headers)\n        return response_class(resp.body, status=resp.status, headers=web_headers)\n'''
if old_tail not in s:
    raise SystemExit('cloudflare_fetch tail anchor missing')
s = s.replace(old_tail, new_tail, 1)

p.write_text(s)
